const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const shell = (title, body, ctaText, ctaUrl) => `
<div style="font-family:Inter,Arial,sans-serif;max-width:560px;margin:0 auto;background:#0f1115;color:#e5e7eb;border-radius:12px;overflow:hidden">
  <div style="background:#FB923C;color:#0f1115;padding:18px 24px;font-size:20px;font-weight:700">OFAI</div>
  <div style="padding:24px">
    <h2 style="margin:0 0 12px;font-size:20px;color:#fff">${title}</h2>
    ${body}
    <p style="margin:24px 0 0"><a href="${ctaUrl}" style="background:#FB923C;color:#0f1115;text-decoration:none;padding:12px 20px;border-radius:8px;font-weight:600;display:inline-block">${ctaText}</a></p>
  </div>
  <div style="padding:14px 24px;font-size:12px;color:#9ca3af;border-top:1px solid #1f2937">Primești acest email pentru că ai un cont pe ofai.ro. <a href="https://ofai.ro/account" style="color:#9ca3af">Preferințe</a></div>
</div>`;
const b = $input.first().json;
const n = Number(b.followers);
const first = n === 1;
const body = first
  ? `<p>Salut, ${esc(b.owner_first_name || '')}! <b>${esc(b.business_name)}</b> are primul urmăritor pe OFAI. De acum, fiecare ofertă nouă ajunge direct la cei care te urmăresc.</p>
     <p>Sfat: publică o <b>ofertă flash</b> săptămâna asta – ofertele cu termen scurt au cele mai multe salvări.</p>`
  : `<p>Felicitări! <b>${esc(b.business_name)}</b> a ajuns la <b>${n} urmăritori</b> pe OFAI.</p>
     <p>Îi poți răsplăti cu o ofertă dedicată – în portal ai statistici pe salvări și coduri dezvăluite.</p>`;
return [{ json: { to: b.owner_email, subject: first ? 'Primul tău urmăritor pe OFAI 🎉' : `${n} urmăritori pe OFAI pentru ${b.business_name} 🚀`, html: shell(first ? 'Primul urmăritor' : `${n} urmăritori`, body, 'Publică o ofertă', 'https://ofai.ro/manage'), followers: n } }];
